from pathlib import Path
from html import escape
D=Path('.')
def t(zh,en):return f'<span data-zh="{escape(zh,quote=True)}" data-en="{escape(en,quote=True)}">{escape(zh)}</span>'
def duo():return '<span class="mini-duo" aria-hidden="true"><i class="pig-art boy"></i><i class="pig-art girl"></i></span>'
def page(name,title,body):
 nav=''.join(f'<a href="{file}"'+(' aria-current="page"' if name==file else '')+'>'+t(zh,en)+'</a>' for file,zh,en in [('primary.html','小學','Primary'),('secondary.html','中學','Secondary')])
 return f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111827"><meta name="description" content="叻豬研究所：Mr. IP 與叻豬陪你玩數學，一起探索小學及中學不同數學課題。"><title>{title}｜叻豬研究所</title><link rel="icon" href="assets/pig-pair.png" type="image/png"><link rel="stylesheet" href="style.css?v=upgrade10"><script defer src="math.js?v=upgrade10"></script><script defer src="app.js?v=upgrade10"></script></head><body data-page="{name.split('.')[0]}"><a class="skip" href="#main">{t('跳至主要內容','Skip to content')}</a><header class="site-header"><nav class="navigation" aria-label="主要導覽"><a class="brand" href="index.html">{duo()}<span><strong>{t('叻豬研究所','Smart Pig Maths Lab')}</strong><small>MR. IP’S MATHS LAB</small></span></a><div class="nav-links">{nav}</div><div class="nav-tools"><button class="icon-button" id="language" aria-label="切換語言 / Switch language">EN</button><button class="icon-button projection-toggle" aria-pressed="false">{t('▣ 投影','▣ Present')}</button></div></nav></header><div class="projection-bar"><span>{t('課室投影模式','Classroom presentation')}</span><div><button id="fullscreen">{t('全螢幕','Full screen')}</button><button class="projection-toggle" aria-pressed="true">{t('返回一般模式','Exit presentation')}</button></div></div><main id="main" class="container">{body}</main><footer class="site-footer"><a href="index.html">叻豬研究所 · SMART PIG MATHS LAB</a><span>{t('每一個「我明白了」，都係新發現。','Every “I get it!” is a new discovery.')}</span></footer><p class="sr-only" id="global-status" role="status"></p></body></html>'''
games=[dict(id='primary-down',room='primary',name='Math Down!',edition='ANIMAL QUEST',image='primary-live.png',url='https://icqm-ip.github.io/Math-Down-Primary/',category='arithmetic',desc=('計啱答案，跳落正確平台。同動物拍檔一齊挑戰四則運算。','Calculate, choose a platform and explore with your animal friends.'),topic=('加、減、乘、除','Addition, subtraction, multiplication, division'),difficulty=('一位至三位數組合；5 檔速度','1–3 digit combinations; 5 speeds'),people=('電腦 1–4 人；觸控單人','Keyboard: 1–4 players; touch: solo'),steps=[('選 Operation 運算種類，再選 Number of digits 位數組合。','Choose Operation and Number of digits.'),('選 Mode 人數及 Speed 速度；手機請先選 Mobile。','Choose Mode and Speed; select Mobile for touch controls.'),('選角色後按 PRESS START。','Choose characters, then press PRESS START.')]),dict(id='secondary-down',room='secondary',name='Math Down!',edition='ALGEBRA QUEST',image='secondary-live.png',url='https://icqm-ip.github.io/Math-Down/',category='algebra',desc=('化簡代數式，跳落答案平台；避開尖刺，留意移動平台。','Simplify expressions, land on the answer platform and avoid spikes.'),topic=('合併同類項、去括號、分數代數式等','Like terms, brackets, algebraic fractions and more'),difficulty=('易／中／難；5 檔速度','Easy / Medium / Hard; 5 speeds'),people=('電腦 1–4 人；觸控單人','Keyboard: 1–4 players; touch: solo'),steps=[('選 Ch3.2 Level 1 題型及 Question difficulty。','Choose a Ch3.2 Level 1 topic and Question difficulty.'),('選 Mode 人數及 Speed 速度；手機請先選 Mobile。','Choose Mode and Speed; select Mobile for touch controls.'),('選老師角色後按 PRESS START。','Choose teacher characters, then press PRESS START.')]),dict(id='volley',room='secondary',name='Math Volley',edition='POLYNOMIAL COURT',image='volley-live.png',url='https://icqm-ip.github.io/math-volley/',category='polynomials',desc=('解多項式、移到球旁、揀答案擊球。與電腦或同學來一場排球對戰。','Solve, move to the ball and choose an answer to hit. Play against a CPU or a friend.'),topic=('合併同類項、指數運算、簡單展開','Like terms, powers and simple expansion'),difficulty=('入門／基礎／挑戰；另設電腦難度','Starter / Basic / Challenge; separate CPU difficulty'),people=('電腦 1–2 人；觸控單人 VS COM','Keyboard: 1–2 players; touch: solo vs CPU'),steps=[('打開「比賽設定」，選 Ch.5 題型及題目難度。','Open Match settings; choose a Ch.5 topic and question difficulty.'),('選 VS COM 或雙人；觸控模式只限 VS COM。','Choose VS COM or two players; touch mode is VS COM only.'),('按「開始比賽」；速度及難度於下一局套用。','Press Start match; settings apply to the next match.')]),dict(id='bomb',room='secondary',name='Math Bomb Battle',edition='POLYNOMIAL BATTLE',image='bomb-live.png',url='https://icqm-ip.github.io/Math-Bomb/',category='polynomials',desc=('閃避水彈，解多項式，再走進 A／B／C 答案傳送門。','Dodge water bombs, solve a polynomial and enter an A/B/C answer portal.'),topic=('概念、化簡、加減乘、展開、恆等式、因式分解','Concepts, simplification, operations, expansion, identities and factorisation'),difficulty=('G7／G8／G9 題庫；Easy／Standard／Challenge','G7 / G8 / G9 banks; Easy / Standard / Challenge'),people=('電腦 1–4 人；觸控單人 VS CPU','Keyboard: 1–4 players; touch: solo vs CPU'),steps=[('選 QUESTION BANK、QUESTION DIFFICULTY，勾選題型。','Choose QUESTION BANK and QUESTION DIFFICULTY; tick topics.'),('選 PLAYERS 及每題時間；手機請先選 Mobile。','Choose PLAYERS and question time; select Mobile for touch.'),('選老師角色，按 START BATTLE。','Choose teachers, then press START BATTLE.')])]
games.append(dict(id='equation-bubble',room='secondary',category='equations'))
def launch(g,label=None):return f'<a class="button game-launch" href="{g["url"]}" target="_blank" rel="noopener noreferrer" aria-label="{g["name"]} — 在新分頁開啟">'+(label or t('開始遊戲','Play game'))+' <span aria-hidden="true">↗</span></a>'
def card(g):
 if g['id']=='equation-bubble':return "<article class=\"game-card equations\" data-category=\"equations\"><div class=\"game-preview\" style=\"background:#172f3b\"><img src=\"equation-bubble-2player.png\" width=\"1280\" height=\"720\" loading=\"lazy\" style=\"object-fit:contain\" alt=\"Equation Bubble 雙人對戰：Mr. IP 對 Ms. Tong\"><span class=\"preview-label\"><span data-zh=\"雙人對戰實際畫面\" data-en=\"Actual two-player gameplay\">雙人對戰實際畫面</span></span></div><div class=\"game-card-body\"><span class=\"eyebrow\">SKY ISLAND ADVENTURE</span><h2 class=\"game-name\">Equation Bubble</h2><p class=\"game-description\"><span data-zh=\"選擇運算，瞄準數字，兩邊一起做；在方程下降前解開答案。\" data-en=\"Choose an operation, aim at a number and apply it to both sides. Solve before the equations fall.\">選擇運算，瞄準數字，兩邊一起做；在方程下降前解開答案。</span></p><dl class=\"game-facts\"><div><dt><span data-zh=\"練習\" data-en=\"Maths\">練習</span></dt><dd><span data-zh=\"一步／兩步方程、兩邊未知數、括號、分數與 LCM\" data-en=\"One-step and two-step equations, variables on both sides, brackets, fractions and LCM\">一步／兩步方程、兩邊未知數、括號、分數與 LCM</span></dd></div><div><dt><span data-zh=\"人數\" data-en=\"Players\">人數</span></dt><dd><span data-zh=\"自主練習／挑戰電腦；電腦雙人對戰\" data-en=\"Solo practice / vs CPU; two players on one keyboard\">自主練習／挑戰電腦；電腦雙人對戰</span></dd></div><div><dt><span data-zh=\"操作\" data-en=\"Controls\">操作</span></dt><dd>⌨ Keyboard · Touch</dd></div></dl><a class=\"button game-launch\" href=\"https://icqm-ip.github.io/Equation-Bubble/\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Equation Bubble — 在新分頁開啟\"><span data-zh=\"開始遊戲\" data-en=\"Play game\">開始遊戲</span> <span aria-hidden=\"true\">↗</span></a></div></article>"
 return f'''<article class="game-card {g['category']}" data-category="{g['category']}"><div class="game-preview"><img src="assets/{g['image']}" width="1280" height="720" loading="lazy" alt="{g['name']} 真實遊戲畫面"><span class="preview-label">{t('實際遊戲畫面','Actual gameplay')}</span></div><div class="game-card-body"><span class="eyebrow">{g['edition']}</span><h2 class="game-name">{g['name']}</h2><p class="game-description">{t(*g['desc'])}</p><dl class="game-facts"><div><dt>{t('練習','Maths')}</dt><dd>{t(*g['topic'])}</dd></div><div><dt>{t('人數','Players')}</dt><dd>{t(*g['people'])}</dd></div><div><dt>{t('操作','Controls')}</dt><dd>⌨ Keyboard · Touch</dd></div></dl>{launch(g)}</div></article>'''
scene=f'''<section class="lab-scene" aria-label="互動數學研究室"><div class="chalkboard" id="chalkboard"><div class="board-heading">{t('一齊玩數學','LET’S PLAY WITH NUMBERS')}</div><div class="board-content"><div class="math-expression" id="question" aria-live="polite"></div><div class="answer-choices" id="answer-choices" aria-label="答案選項"></div></div><div class="board-response"><p class="challenge-feedback" id="challenge-feedback" role="status" aria-live="polite"></p><button class="board-tool" id="next-question">{t('再玩一題 ↻','Another one ↻')}</button></div><div class="chalk-tray" aria-hidden="true"><i></i><i></i><b></b></div><span class="correct-stars" aria-hidden="true">✦ ★ ✦</span></div><div class="classroom-cast"><div class="teacher-host" role="img" aria-label="Mr. IP"><span class="teacher-art"></span></div><button class="pig-host" data-pig="boy" aria-label="跟男仔叻豬打招呼"><span class="pig-art boy" aria-hidden="true"></span></button><button class="pig-host" data-pig="girl" aria-label="跟女仔叻豬打招呼"><span class="pig-art girl" aria-hidden="true"></span></button></div><div class="speech-lane" aria-live="polite"><p id="pig-bubble" class="pig-bubble" hidden></p></div></section>'''
doors=f'''<section id="rooms" class="room-section" aria-labelledby="rooms-title"><div class="section-heading"><div><span class="eyebrow">CHOOSE YOUR ADVENTURE</span><h2 id="rooms-title">{t('揀一間研究室，開始探索','Choose a lab. Start exploring.')}</h2></div></div><div class="room-grid"><a class="room-card primary-room" href="primary.html"><span class="room-symbol" aria-hidden="true">＋</span><span class="eyebrow">PRIMARY LAB · 01 GAME</span><h3>{t('小學研究室','Primary Lab')}</h3><p>{t('打好數感基礎，和動物拍檔挑戰加減乘除。','Build number sense. Explore arithmetic with animal friends.')}</p><span class="room-enter">{t('進入小學研究室','Explore Primary Lab')} ↗</span></a><a class="room-card secondary-room" href="secondary.html"><span class="room-symbol" aria-hidden="true">x²</span><span class="eyebrow">SECONDARY LAB · 04 GAMES</span><h3>{t('中學研究室','Secondary Lab')}</h3><p>{t('探索不同數學課題，用思考與策略解鎖下一關。','Explore maths topics. Unlock the next level with thinking and strategy.')}</p><span class="room-enter">{t('進入中學研究室','Explore Secondary Lab')} ↗</span></a></div></section>'''
home=f'''<section class="home-hero"><div class="hero-intro"><span class="eyebrow">PLAY · THINK · DISCOVER</span><h1>{t('叻豬研究所','Smart Pig Maths Lab')}</h1><p class="hero-tagline">{t('玩住諗，諗住學。','Play. Think. Discover.')}</p><p>{t('跟 Mr. IP 同叻豬，由一道心算，走進一場數學冒險。','Join Mr. IP and the Smart Pigs. Start with a question; discover an adventure.')}</p><div class="hero-entrances"><a class="button" href="primary.html">{t('小學研究室','Primary Lab')} ↗</a><a class="button cyan" href="secondary.html">{t('中學研究室','Secondary Lab')} ↗</a></div></div>{scene}</section>{doors}'''
D.joinpath('index.html').write_text(page('index.html','首頁',home))
for room,zh,en in [('primary','小學研究室','Primary Lab'),('secondary','中學研究室','Secondary Lab')]:
 selected=[g for g in games if g['room']==room]
 filters='' if room=='primary' else '<div class="filters" aria-label="按課題篩選">'+''.join(f'<button data-filter="{val}" aria-pressed="{str(val=="all").lower()}">{t(a,b)}</button>' for val,a,b in [('all','全部遊戲','All games'),('algebra','代數化簡','Algebra'),('polynomials','多項式','Polynomials'),('equations','解方程','Equations')])+'</div>'
 body=f'''<div class="page-heading"><div><a class="back-link" href="index.html">← {t('返回研究所','Back to the lab')}</a><span class="eyebrow">{'PRIMARY · ARITHMETIC' if room=='primary' else 'SECONDARY · MATHS ADVENTURES'}</span><h1>{t(zh,en)}</h1><p>{t('先學懂，再闖關。揀一款遊戲，開始今日的數學冒險。','Learn a skill. Take on a challenge. Choose your next maths adventure.')}</p></div>{duo()}</div>{filters}<p class="filter-count" id="filter-count" role="status"></p><div class="game-grid">{''.join(card(g) for g in selected)}</div><aside class="help-strip"><strong>{t('第一次玩？','First time?')}</strong><p>{t('先揀慢速，熟習操作。多人模式請用電腦鍵盤；手機及平板請在遊戲內選觸控模式。','Start slowly and practise the controls. Use a keyboard for multiplayer; select touch mode for phones and tablets.')}</p></aside><p class="newtab-note">↗ {t('遊戲在新分頁開啟，研究所會留在原本分頁。','Games open in a new tab. The lab stays here for you.')}</p>'''
 D.joinpath(room+'.html').write_text(page(room+'.html',zh,body))